#define PIN_SPEED    0  // PB0: Вход датчика движения (0 - едем)
#define PIN_HANDED   1  // PB1: Вход ручника (0 - затянут)
#define PIN_LIGHTS_IN 2 // PB2: Вход габаритов с кнопки (1 - включены вручную)
#define PIN_AUTO_LIGHT 3 // PB3: Выход на транзистор управления реле

bool auto_mode = false;      
bool last_hand_state = true; 
unsigned long hand_press_time = 0; 
int hand_counter = 0;        
bool block_auto_until_stop = false; // Флаг блокировки авто-света, если водитель нажал кнопку в движении

void setup() {
  pinMode(PIN_SPEED, INPUT_PULLUP);
  pinMode(PIN_HANDED, INPUT_PULLUP);
  pinMode(PIN_LIGHTS_IN, INPUT); // Внешний делитель напряжения

  pinMode(PIN_AUTO_LIGHT, OUTPUT);
  digitalWrite(PIN_AUTO_LIGHT, LOW);
}

void loop() {
  bool speed_signal = digitalRead(PIN_SPEED);
  bool hand_signal = digitalRead(PIN_HANDED);
  bool button_lights = digitalRead(PIN_LIGHTS_IN);

  // Если машина остановилась, сбрасываем блокировку автоматики
  if (speed_signal == HIGH) {
    block_auto_until_stop = false;
  }

  // 1. Движение (Включаем свет, только если нет блокировки)
  if (speed_signal == LOW && !block_auto_until_stop) {
    auto_mode = true;
  }

  // 2. Кнопка габаритов гасит авто-свет
  // (Сработает, только если физически развязать кнопку диодом или 5-конт. реле!)
  if (button_lights == HIGH) {
    auto_mode = false;
    hand_counter = 0; 
    if (speed_signal == LOW) {
      block_auto_until_stop = true; // Запрещаем авто-включение, пока снова не остановимся
    }
  }

  // 3. Ручник (2 раза за 10 сек)
  if (hand_signal == LOW && last_hand_state == HIGH) {
    delay(50); // Антидребезг контактов ручника
    if (digitalRead(PIN_HANDED) == LOW) { 
      if (hand_counter == 0) {
        hand_press_time = millis(); 
        hand_counter = 1;
      } else if (hand_counter == 1) {
        if (millis() - hand_press_time <= 10000) {
          if (speed_signal == HIGH) { // Отключаем свет только если машина стоит
            auto_mode = false;
          }
        }
        hand_counter = 0; 
      }
    }
  }
  last_hand_state = hand_signal;

  if (hand_counter == 1 && (millis() - hand_press_time > 10000)) {
    hand_counter = 0;
  }

  // 4. Управление транзистором
  if (auto_mode) {
    digitalWrite(PIN_AUTO_LIGHT, HIGH); 
  } else {
    digitalWrite(PIN_AUTO_LIGHT, LOW);  
  }
}
